oxy_webhelp_navlinks = {"aws_deploy_self_managed-d39536e16186":{"topics":[{"title":"Deployment checklist for self-managed AWS protection","shortdesc":"<p class=\"shortdesc\">Use this pre-flight checklist to confirm that the licenses, access, permissions,         network, and storage are in place before you add an AWS account that uses the self-managed         deployment model.<\/p>","href":"saas\/aws_deployment_checklist_self_managed.html","attributes":{"data-id":"aws_deployment_checklist_self_managed"},"menu":{"hasChildren":false},"tocID":"aws_deployment_checklist_self_managed-d39536e16197","topics":[]},{"title":"Plan your self-managed AWS protection","shortdesc":"<p class=\"shortdesc\">Before you add an AWS account, confirm your license, permissions, account setup         options, and, if you use them, Exocompute and storage tiering.<\/p>","href":"saas\/aws_customer_hosted_planning.html","attributes":{"data-id":"aws_customer_hosted_planning"},"menu":{"hasChildren":false},"tocID":"aws_customer_hosted_planning-d39536e16208","next":"aws_customer_hosted_planning-d39536e16208"},{"title":"Set up AWS cloud accounts","shortdesc":"<p class=\"shortdesc\">You can set up an AWS cloud account in <span class=\"ph\">RSC<\/span> and start protecting your         AWS workloads.<\/p>","href":"saas\/aws_cloud_acc_setup.html","attributes":{"data-id":"aws_cloud_acc_setup"},"menu":{"hasChildren":false},"tocID":"aws_cloud_acc_setup-d39536e16613","next":"aws_cloud_acc_setup-d39536e16613"},{"title":"Set up Exocompute on AWS","shortdesc":"<p class=\"shortdesc\">With the Exocompute on AWS feature, <span class=\"ph\">RSC<\/span> launches an Elastic         Kubernetes Service cluster to perform various operations to protect AWS workloads. <span class=\"ph\">RSC<\/span> uses the Elastic Kubernetes Service cluster as a compute resource in         your AWS account.<\/p>","href":"saas\/exocompute_for_aws.html","attributes":{"data-id":"exocompute_for_aws"},"menu":{"hasChildren":false},"tocID":"exocompute_for_aws-d39536e16881","next":"exocompute_for_aws-d39536e16881"},{"title":"Set up AWS storage tiering","shortdesc":"<p class=\"shortdesc\">You can use AWS storage tiering to archive Amazon EC2 instance<span class=\"ph\">, EBS volume, or DynamoDB table<\/span> snapshots         that exceed a specified threshold to Amazon S3 storage classes. By archiving snapshots to         these storage classes, you can optimize costs.<\/p>","href":"saas\/aws_storage_tiering_setup.html","attributes":{"data-id":"aws_storage_tiering_setup"},"menu":{"hasChildren":false},"tocID":"aws_storage_tiering_setup-d39536e17493","next":"aws_storage_tiering_setup-d39536e17493"}]}};